import{_ as t,o as r,c as o,aa as a,j as i}from"./chunks/framework.BAs_AphD.js";const h=JSON.parse('{"title":"Stavební deník","description":"","frontmatter":{"title":"Stavební deník","wiki":"cs:diary:start"},"headers":[],"relativePath":"diary/index.md","filePath":"diary/index.md","lastUpdated":1794209661000}'),d={name:"diary/index.md"};function n(l,e,p,s,k,v){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="stavebni-denik" tabindex="-1">Stavební deník <a class="header-anchor" href="#stavebni-denik" aria-label="Permalink to &quot;Stavební deník&quot;">​</a></h1><p>Modul <strong>Stavební deník</strong> slouží k vedení stavebního deníku v elektronické formě podle platných právních předpisů České a Slovenské republiky. Záznamy pořizujete na webu i v mobilní aplikaci a podepisujete je elektronickým podpisem.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/zalozeni-stavby">Založit novou stavbu</a>, <a href="/buildary-help-preview/akademie/zalozeni-deniku">Založit stavební deník</a> a <a href="/buildary-help-preview/akademie/den-v-deniku">Pochopit, jak funguje den v deníku</a> v Akademii.</p>',3),i("div",{class:"video"},[i("iframe",{src:"https://www.youtube-nocookie.com/embed/WDvGcYxvM88",title:"Video: Stavební deník v Buildary",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),a('<h2 id="co-denik-umi" tabindex="-1">Co deník umí <a class="header-anchor" href="#co-denik-umi" aria-label="Permalink to &quot;Co deník umí&quot;">​</a></h2><ul><li>Na jedné stavbě vedete libovolný počet deníků – například centrální deník, deníky stavebních objektů nebo deníky podzhotovitelů.</li><li>Deník je oprávněným osobám dostupný kdykoli a odkudkoli, kde je internet. Data jsou uložená v cloudu Microsoft Azure a neopustí území Evropské unie – viz <a href="/buildary-help-preview/firstofall/#kde-jsou-vase-data">Co je Buildary</a>.</li><li>Každý den deníku podepíšete elektronickým podpisem a tím ho uzamknete proti změnám.</li><li>Záznamy můžete propojit s ostatními moduly: k záznamu v deníku založíte úkol v <a href="/buildary-help-preview/tickets/">Managementu úkolů</a>, ve výkresech stavby označíte místo, kterého se záznam týká.</li></ul><h2 id="jak-s-denikem-pracovat" tabindex="-1">Jak s deníkem pracovat <a class="header-anchor" href="#jak-s-denikem-pracovat" aria-label="Permalink to &quot;Jak s deníkem pracovat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Krok</th><th>Co uděláte</th><th>Kde je popsáno</th></tr></thead><tbody><tr><td>1. Připravit stavbu</td><td>Založíte stavbu, přidáte firmy a lidi, rozdělíte stavbu na části a připravíte číselníky.</td><td><a href="/buildary-help-preview/diary/projectsetup">Založit stavbu</a>, <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>, <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>, <a href="/buildary-help-preview/diary/codelists">Číselníky deníku</a></td></tr><tr><td>2. Založit a nastavit deník</td><td>Založíte deník, vyplníte jeho identifikační údaje a určíte, kdo do něj smí zapisovat.</td><td><a href="/buildary-help-preview/diary/diarysetup">Založit deník</a>, <a href="/buildary-help-preview/diary/diarysettings">Nastavit deník</a>, <a href="/buildary-help-preview/diary/diaryidentification">Identifikační údaje deníku</a>, <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a></td></tr><tr><td>3. Zapisovat den</td><td>Každý pracovní den zapíšete počasí, osoby, stroje, materiály, provedené práce a další záznamy.</td><td><a href="/buildary-help-preview/diary/dailyentries">Denní záznamy</a>, <a href="/buildary-help-preview/diary/dailyentriespersons">Počasí, osoby, stroje a materiály</a>, <a href="/buildary-help-preview/diary/dailyentriesworks">Provedené práce</a>, <a href="/buildary-help-preview/diary/dailyentriesothers">Další záznamy</a>, <a href="/buildary-help-preview/diary/copydailyentries">Kopírovat záznamy</a></td></tr><tr><td>4. Podepsat</td><td>Den podepíšete a tím ho uzamknete.</td><td><a href="/buildary-help-preview/diary/signing">Podepisování deníku</a>, <a href="/buildary-help-preview/diary/signaturesetting">Způsoby podpisu</a>, <a href="/buildary-help-preview/diary/externalappsignature">Podpis v externí aplikaci</a>, <a href="/buildary-help-preview/diary/signingwithout">Bez elektronického podpisu</a></td></tr><tr><td>5. Výstupy</td><td>Deník vytisknete, stáhnete nebo v něm vyhledáte záznamy.</td><td><a href="/buildary-help-preview/diary/download">Tisk a export deníku</a>, <a href="/buildary-help-preview/diary/reports">Přehledy</a></td></tr><tr><td>6. Ukončit stavbu</td><td>Po dokončení stavbu archivujete nebo pošlete ke smazání.</td><td><a href="/buildary-help-preview/diary/projectended">Ukončit stavbu</a></td></tr></tbody></table><p>Deník můžete napojit i na další systémy – viz <a href="/buildary-help-preview/diary/attendance_system">Docházkový systém</a> a <a href="/buildary-help-preview/diary/sensors">Čidla a odkaz na stavbu</a>.</p><h2 id="denik-v-mobilu" tabindex="-1">Deník v mobilu <a class="header-anchor" href="#denik-v-mobilu" aria-label="Permalink to &quot;Deník v mobilu&quot;">​</a></h2><p>Stavbu a deník nejdřív připravte ve webové aplikaci – založení a nastavení stavby, projektového týmu a deníků v mobilu nejde (viz <a href="/buildary-help-preview/firstofall/mobile#co-se-dela-jen-na-webu">Co se dělá jen na webu</a>). Na stavbě pak v <a href="/buildary-help-preview/firstofall/mobile">mobilní aplikaci</a>:</p><ul><li><a href="/buildary-help-preview/diary/m_project_list">otevřete stavbu a deník</a>,</li><li><a href="/buildary-help-preview/diary/m_dailyentries">zapisujete denní záznamy</a> včetně fotek,</li><li><a href="/buildary-help-preview/diary/m_signing">podepisujete</a> – podpisový certifikát si do telefonu <a href="/buildary-help-preview/diary/m_certificate">přenesete z počítače</a>,</li><li>pracujete i bez signálu v <a href="/buildary-help-preview/diary/m_offline">offline režimu</a>.</li></ul><h2 id="pravni-predpisy" tabindex="-1">Právní předpisy <a class="header-anchor" href="#pravni-predpisy" aria-label="Permalink to &quot;Právní předpisy&quot;">​</a></h2><p>Elektronickou formu stavebního deníku dnešní legislativa výslovně připouští a v některých případech ji přímo nařizuje. Řešení v Buildary vychází ze stanovisek našich partnerských právních poradců.</p><h3 id="ceska-republika" tabindex="-1">Česká republika <a class="header-anchor" href="#ceska-republika" aria-label="Permalink to &quot;Česká republika&quot;">​</a></h3><ul><li>§ 166 zákona č. 283/2021 Sb., stavební zákon</li><li>příloha č. 12 vyhlášky č. 131/2024 Sb., o dokumentaci staveb</li><li>§ 5 a § 6 zákona č. 297/2016 Sb., o službách vytvářejících důvěru pro elektronické transakce</li></ul><h3 id="slovenska-republika" tabindex="-1">Slovenská republika <a class="header-anchor" href="#slovenska-republika" aria-label="Permalink to &quot;Slovenská republika&quot;">​</a></h3><ul><li>§ 46d zákona č. 50/1976 Zb. o územnom plánovaní a stavebnom poriadku (stavebný zákon)</li><li>§ 28 vyhlášky Ministerstva životného prostredia č. 453/2000 Z. z., ktorou sa vykonávajú niektoré ustanovenia stavebného zákona</li><li>zákon č. 272/2016 Z. z. o dôveryhodných službách pre elektronické transakcie na vnútornom trhu (zákon o dôveryhodných službách)</li><li>zákon č. 305/2013 Z. z. o elektronickej podobe výkonu pôsobnosti orgánov verejnej moci (zákon o e-Governmente)</li></ul><p>Na Slovensku doporučujeme, aby se účastníci výstavby na elektronické formě deníku dohodli písemně, například odstavcem ve smlouvě o dílo nebo zápisem z jednání.</p><div class="tip custom-block"><p class="custom-block-title">Když někdo nemůže podepsat elektronicky</p><p>Deník můžete vést elektronicky i tehdy, když některá z osob elektronický podpis nemá. Jak postupovat, popisuje <a href="/buildary-help-preview/diary/signingwithout">Bez elektronického podpisu</a>.</p></div>',16)])])}const y=t(d,[["render",n]]);export{h as __pageData,y as default};
